export type Options<TData extends TDataShape = TDataShape, ThrowOnError extends boolean = boolean, TResponse = unknown> = Options2<TData, ThrowOnError, TResponse> & {
    /**
     * You can provide a client instance returned by `createClient()` instead of
     * individual options. This might be also useful if you want to implement a
     * custom client.
     */
    client?: Client;
    /**
     * You can pass arbitrary values through the `meta` object. This can be
     * used to access values that aren't defined as part of the SDK function.
     */
    meta?: keyof ClientMeta extends never ? Record<string, unknown> : ClientMeta;
};

/**
 * Service health — the walking-skeleton control-plane round trip.
 */
export const healthRead = <ThrowOnError extends boolean = false>(options?: Options<HealthReadData, ThrowOnError>): RequestResult<HealthReadResponses, HealthReadErrors, ThrowOnError> => (options?.client ?? client).get<HealthReadResponses, HealthReadErrors, ThrowOnError>({ url: '/api/health', ...options });

/**
 * The session user, their firm, and their effective permissions — the SPA's bootstrap call. A person who has not yet joined a firm answers with a null firm, no permissions, and what the joining surface should show them next.
 */
export const meGet = <ThrowOnError extends boolean = false>(options?: Options<MeGetData, ThrowOnError>): RequestResult<MeGetResponses, MeGetErrors, ThrowOnError> => (options?.client ?? client).get<MeGetResponses, MeGetErrors, ThrowOnError>({ url: '/api/v1/me', ...options });

/**
 * Lists the firm's members — display name, status, the roles held, and whether a professional profile has been written. Deactivated members are included: they still hold matters. Not paged; a firm's roster is bounded by its headcount rather than by its activity.
 */
export const membersList = <ThrowOnError extends boolean = false>(options?: Options<MembersListData, ThrowOnError>): RequestResult<MembersListResponses, MembersListErrors, ThrowOnError> => (options?.client ?? client).get<MembersListResponses, MembersListErrors, ThrowOnError>({ url: '/api/v1/members', ...options });

/**
 * Invites a member into the session firm: creates the (unverified, account-less) user, enqueues the per-firm member.provision outbox row, audits the invite — one atomic batch — then sends the activation email (a password-reset link; the reset creates the credential).
 */
export const membersInvite = <ThrowOnError extends boolean = false>(options: Options<MembersInviteData, ThrowOnError>): RequestResult<MembersInviteResponses, MembersInviteErrors, ThrowOnError> => (options.client ?? client).post<MembersInviteResponses, MembersInviteErrors, ThrowOnError>({
    url: '/api/v1/members',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Lists the firm's roles: what each one is called, the permissions it carries, and how many active members hold it. The reference a person consults before granting one — a role name alone says nothing about what it lets somebody do.
 */
export const rolesList = <ThrowOnError extends boolean = false>(options?: Options<RolesListData, ThrowOnError>): RequestResult<RolesListResponses, RolesListErrors, ThrowOnError> => (options?.client ?? client).get<RolesListResponses, RolesListErrors, ThrowOnError>({ url: '/api/v1/roles', ...options });

/**
 * Sets the roles a member holds, as a whole set. Refused when the actor is the subject, when the set names a sub-role without its parent role or two sub-roles of one parent, and when the change would leave the firm with no active member who can administer its members. Returns the roles held after the write.
 */
export const membersSetRoles = <ThrowOnError extends boolean = false>(options: Options<MembersSetRolesData, ThrowOnError>): RequestResult<MembersSetRolesResponses, MembersSetRolesErrors, ThrowOnError> => (options.client ?? client).put<MembersSetRolesResponses, MembersSetRolesErrors, ThrowOnError>({
    url: '/api/v1/members/{userId}/roles',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Deactivates a member: their sessions stop resolving to any capability, and their rows stay. A deactivated member is still the responsible attorney on the matters they carried and the author of what they filed, so the roster keeps listing them. Refused when the actor is the subject, and refused for the last member who can administer the firm.
 */
export const membersDeactivate = <ThrowOnError extends boolean = false>(options: Options<MembersDeactivateData, ThrowOnError>): RequestResult<MembersDeactivateResponses, MembersDeactivateErrors, ThrowOnError> => (options.client ?? client).post<MembersDeactivateResponses, MembersDeactivateErrors, ThrowOnError>({ url: '/api/v1/members/{userId}/deactivation', ...options });

/**
 * Returns a deactivated member to active. They hold whatever roles they held when they left — deactivation suspends a member's access rather than stripping what they were given, so a return does not mean re-granting it by hand.
 */
export const membersReactivate = <ThrowOnError extends boolean = false>(options: Options<MembersReactivateData, ThrowOnError>): RequestResult<MembersReactivateResponses, MembersReactivateErrors, ThrowOnError> => (options.client ?? client).post<MembersReactivateResponses, MembersReactivateErrors, ThrowOnError>({ url: '/api/v1/members/{userId}/reactivation', ...options });

/**
 * The session member's own name: the parts they have stated, the line those parts read as, and whether they have ever stated them. A person who has not reads the single name their account was created with, and their parts read as null — never as a guess at how that line splits.
 */
export const meName = <ThrowOnError extends boolean = false>(options?: Options<MeNameData, ThrowOnError>): RequestResult<MeNameResponses, MeNameErrors, ThrowOnError> => (options?.client ?? client).get<MeNameResponses, MeNameErrors, ThrowOnError>({ url: '/api/v1/me/name', ...options });

/**
 * Sets the session member's own name, as the whole set of parts. The rendered line is composed from them in the same statement, so what the platform prints and what the person stated can never disagree, and the firm's roster is updated to match. Refused when every part is empty: a person always has a name, and clearing it would leave every record they touched unnamed.
 */
export const meSetName = <ThrowOnError extends boolean = false>(options: Options<MeSetNameData, ThrowOnError>): RequestResult<MeSetNameResponses, MeSetNameErrors, ThrowOnError> => (options.client ?? client).put<MeSetNameResponses, MeSetNameErrors, ThrowOnError>({
    url: '/api/v1/me/name',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Removes the session member's own picture. A member who holds none is answered the same way: the act says what is true afterwards, not what was true before.
 */
export const meRemovePhoto = <ThrowOnError extends boolean = false>(options?: Options<MeRemovePhotoData, ThrowOnError>): RequestResult<MeRemovePhotoResponses, MeRemovePhotoErrors, ThrowOnError> => (options?.client ?? client).delete<MeRemovePhotoResponses, MeRemovePhotoErrors, ThrowOnError>({ url: '/api/v1/me/photo', ...options });

/**
 * The session member's own picture, as facts about it — what the bytes are, how large they are, and when they were set. Null where they hold none. The bytes themselves are a separate read.
 */
export const mePhoto = <ThrowOnError extends boolean = false>(options?: Options<MePhotoData, ThrowOnError>): RequestResult<MePhotoResponses, MePhotoErrors, ThrowOnError> => (options?.client ?? client).get<MePhotoResponses, MePhotoErrors, ThrowOnError>({ url: '/api/v1/me/photo', ...options });

/**
 * Sets the session member's own picture, replacing whatever they held. The bytes are read to decide what they are — a PNG or a JPEG, and nothing else — so nothing can be stored that a screen will later refuse to draw.
 */
export const meSetPhoto = <ThrowOnError extends boolean = false>(options: Options<MeSetPhotoData, ThrowOnError>): RequestResult<MeSetPhotoResponses, MeSetPhotoErrors, ThrowOnError> => (options.client ?? client).put<MeSetPhotoResponses, MeSetPhotoErrors, ThrowOnError>({
    url: '/api/v1/me/photo',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * The bytes of the session member's own picture, in the type they were sniffed to be when they were stored. Rides the session like every other read and is never publicly addressable.
 */
export const mePhotoContent = <ThrowOnError extends boolean = false>(options?: Options<MePhotoContentData, ThrowOnError>): RequestResult<MePhotoContentResponses, MePhotoContentErrors, ThrowOnError> => (options?.client ?? client).get<MePhotoContentResponses, MePhotoContentErrors, ThrowOnError>({ url: '/api/v1/me/photo/content', ...options });

/**
 * A one-minute, one-use address on the community board that signs the session member in there. Fetched at the moment they choose to go, never ahead of time.
 */
