export const reportsPaymentsApplied = <ThrowOnError extends boolean = false>(options: Options<ReportsPaymentsAppliedData, ThrowOnError>): RequestResult<ReportsPaymentsAppliedResponses, ReportsPaymentsAppliedErrors, ThrowOnError> => (options.client ?? client).get<ReportsPaymentsAppliedResponses, ReportsPaymentsAppliedErrors, ThrowOnError>({ url: '/api/v1/reports/payments-applied', ...options });

