/**
 * Searches one matter across every section the member may read, answering one group per source in the matter's own section order. Pass `in` (repeatable) to narrow to named sources; absent means every source the member may read, and there is no value meaning wider than this matter. A group that contributed nothing says why — a source the member lacks the capability for is reported as withheld rather than returned empty, so a search never reads as 'this matter holds nothing' when it holds something the reader cannot see.
 */
export const matterSearchSearch = <ThrowOnError extends boolean = false>(options: Options<MatterSearchSearchData, ThrowOnError>): RequestResult<MatterSearchSearchResponses, MatterSearchSearchErrors, ThrowOnError> => (options.client ?? client).get<MatterSearchSearchResponses, MatterSearchSearchErrors, ThrowOnError>({ url: '/api/v1/matters/{matterId}/search', ...options });

/**
 * Searches every matter the member may see, answering one group per place in the order a matter's own sections read in. Each hit names its matter and links to its own section there. Pass `in` (repeatable) to narrow to named places. A place that contributed nothing says why: `one-matter-only` is a place searched inside a matter and not across them, `permission` is one the member lacks the capability for, and `too-many-matters` is a place searched only where the search reaches few enough matters to ask each one, which a member changes by narrowing it to `fewMattersLimit` matters or fewer. `broad` is true when the words are in more of the firm's records than one search reads; the groups then hold the most recent records with those words and not every one. A long text is quoted at the stretch the words are in, and `titleMarks` and `snippetMarks` say where they are in what is shown. `mine=true` narrows the search to the matters the member is responsible for or currently assigned to, and `clientEntityId` to the matters one person or organization is a client on; neither reaches a matter the member may not see.
 */
export const searchAcrossMatters = <ThrowOnError extends boolean = false>(options: Options<SearchAcrossMattersData, ThrowOnError>): RequestResult<SearchAcrossMattersResponses, SearchAcrossMattersErrors, ThrowOnError> => (options.client ?? client).get<SearchAcrossMattersResponses, SearchAcrossMattersErrors, ThrowOnError>({ url: '/api/v1/search', ...options });

