/**
 * Adds a member to this review set's access list. Granting somebody who is already listed is a no-op rather than a conflict. Widening who may see a corpus is recorded, because it is the same order of decision as deciding what leaves the firm.
 */
export const discoveryGrantReviewSetAccess = <ThrowOnError extends boolean = false>(options: Options<DiscoveryGrantReviewSetAccessData, ThrowOnError>): RequestResult<DiscoveryGrantReviewSetAccessResponses, DiscoveryGrantReviewSetAccessErrors, ThrowOnError> => (options.client ?? client).put<DiscoveryGrantReviewSetAccessResponses, DiscoveryGrantReviewSetAccessErrors, ThrowOnError>({ url: '/api/v1/review-sets/{reviewSetId}/access/{memberUserId}', ...options });

/**
 * This review set's coding questions and their answers, in the order a reviewer sees them. Every review set is seeded with Responsiveness, Privilege and Confidentiality; a firm renames them freely and adds its own issue codes beside them.
 */
export const discoveryGetCodingPanel = <ThrowOnError extends boolean = false>(options: Options<DiscoveryGetCodingPanelData, ThrowOnError>): RequestResult<DiscoveryGetCodingPanelResponses, DiscoveryGetCodingPanelErrors, ThrowOnError> => (options.client ?? client).get<DiscoveryGetCodingPanelResponses, DiscoveryGetCodingPanelErrors, ThrowOnError>({ url: '/api/v1/review-sets/{reviewSetId}/coding-panel', ...options });

/**
 * Adds a coding question to this review set. A single-choice question is a radio row and a multi-choice question is a flag set; the cardinality is what stops a document being coded two contradictory ways, and it is enforced by the database rather than by the surface.
 */
export const discoveryCreateCodingQuestion = <ThrowOnError extends boolean = false>(options: Options<DiscoveryCreateCodingQuestionData, ThrowOnError>): RequestResult<DiscoveryCreateCodingQuestionResponses, DiscoveryCreateCodingQuestionErrors, ThrowOnError> => (options.client ?? client).post<DiscoveryCreateCodingQuestionResponses, DiscoveryCreateCodingQuestionErrors, ThrowOnError>({
    url: '/api/v1/review-sets/{reviewSetId}/coding-panel/questions',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Adds an answer to a coding question. A tag created here carries no machine meaning and drives no production behaviour — it filters, groups and exports. The answers production and privilege logging resolve through are the seeded ones, so that renaming a label can never change what a production withholds.
 */
export const discoveryCreateCodingTag = <ThrowOnError extends boolean = false>(options: Options<DiscoveryCreateCodingTagData, ThrowOnError>): RequestResult<DiscoveryCreateCodingTagResponses, DiscoveryCreateCodingTagErrors, ThrowOnError> => (options.client ?? client).post<DiscoveryCreateCodingTagResponses, DiscoveryCreateCodingTagErrors, ThrowOnError>({
    url: '/api/v1/review-sets/{reviewSetId}/coding-panel/questions/{reviewTagGroupId}/tags',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Renames a coding question. Renaming is the only edit it takes, and a seeded question renames as freely as one the firm added: nothing ever matched a question by its name.
 */
export const discoveryUpdateCodingQuestion = <ThrowOnError extends boolean = false>(options: Options<DiscoveryUpdateCodingQuestionData, ThrowOnError>): RequestResult<DiscoveryUpdateCodingQuestionResponses, DiscoveryUpdateCodingQuestionErrors, ThrowOnError> => (options.client ?? client).patch<DiscoveryUpdateCodingQuestionResponses, DiscoveryUpdateCodingQuestionErrors, ThrowOnError>({
    url: '/api/v1/review-sets/{reviewSetId}/coding-panel/questions/{reviewTagGroupId}',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Renames a tag, or takes it out of use. A tag is never deleted: it is on every document anybody ever applied it to, and deleting it would erase the coding history those rows exist to keep. Deactivating hides it from the panel and leaves all of that readable. A tag carrying a machine meaning cannot be deactivated at all, because production and privilege logging resolve through it — rename it instead.
 */
