/**
 * Applies or removes a tag on one document, or on its whole family. A family gesture writes a row per family member rather than one row the members inherit, so what a production later reads is the decision itself and not a rule about decisions. Answering a single-choice question again replaces the previous answer, which is kept — removal is a state with an actor and an instant, never a deletion.
 */
export const discoveryApplyCoding = <ThrowOnError extends boolean = false>(options: Options<DiscoveryApplyCodingData, ThrowOnError>): RequestResult<DiscoveryApplyCodingResponses, DiscoveryApplyCodingErrors, ThrowOnError> => (options.client ?? client).post<DiscoveryApplyCodingResponses, DiscoveryApplyCodingErrors, ThrowOnError>({
    url: '/api/v1/review-sets/{reviewSetId}/documents/{reviewDocumentId}/coding',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Applies or removes a tag across a named set of documents. The selection is resolved ONCE and frozen before anything is written, and the operation walks that frozen list: a selection re-resolved as it went would tag documents the person who started it never saw. The criteria that produced it are recorded alongside for whoever reads the history later. Documents outside this review set are dropped from the selection rather than named.
 */
export const discoveryBulkCoding = <ThrowOnError extends boolean = false>(options: Options<DiscoveryBulkCodingData, ThrowOnError>): RequestResult<DiscoveryBulkCodingResponses, DiscoveryBulkCodingErrors, ThrowOnError> => (options.client ?? client).post<DiscoveryBulkCodingResponses, DiscoveryBulkCodingErrors, ThrowOnError>({
    url: '/api/v1/review-sets/{reviewSetId}/coding/bulk',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Takes back one coding act, exactly. It reverses precisely the rows that act wrote and which are still current — a tag somebody applied independently afterwards is untouched, and a row already removed keeps its original attribution. Nothing is deleted: the reversed act stays in the history pointing at the act that reversed it. An undo is itself an act and is not undone.
 */
