export const trustDeposit = <ThrowOnError extends boolean = false>(options: Options<TrustDepositData, ThrowOnError>): RequestResult<TrustDepositResponses, TrustDepositErrors, ThrowOnError> => (options.client ?? client).post<TrustDepositResponses, TrustDepositErrors, ThrowOnError>({
    url: '/api/v1/trust/deposits',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Lists the disbursement requests on one trust account that nobody has decided yet, oldest first — the queue an approving member works from. A request leaves this list the moment it is approved, rejected, or withdrawn.
 */
export const trustListDisbursementRequests = <ThrowOnError extends boolean = false>(options: Options<TrustListDisbursementRequestsData, ThrowOnError>): RequestResult<TrustListDisbursementRequestsResponses, TrustListDisbursementRequestsErrors, ThrowOnError> => (options.client ?? client).get<TrustListDisbursementRequestsResponses, TrustListDisbursementRequestsErrors, ThrowOnError>({ url: '/api/v1/trust/disbursement-requests', ...options });

/**
 * Proposes a payment of client money out of a matter's trust ledger, and — when the firm's posture lets this member release it alone — makes the payment in the same atomic write. The firm decides which: a member holding the authority to act on client money releases an amount that needs no second person by themselves, and the response says `approved` with the movement it posted; anybody else leaves a pending request that somebody who holds the authority has to approve, and the response says `pending`, names who can approve it, and moves no money at all — no ledger entry, no balance change, no movement record. Either way the proposal is checked against the ledger's AVAILABLE balance (the stored balance less any disputed-funds holds), and a request that stays pending is checked again when it is approved.
 */
export const trustRequestDisbursement = <ThrowOnError extends boolean = false>(options: Options<TrustRequestDisbursementData, ThrowOnError>): RequestResult<TrustRequestDisbursementResponses, TrustRequestDisbursementErrors, ThrowOnError> => (options.client ?? client).post<TrustRequestDisbursementResponses, TrustRequestDisbursementErrors, ThrowOnError>({
    url: '/api/v1/trust/disbursement-requests',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Approves a pending disbursement request and posts the trust movement, in one atomic write. The approving member must be somebody other than the member who submitted the request, and is recorded on the movement as the authorizing member; the submitter stays recorded as the member who entered the record. The available balance is measured again HERE, against the ledger as it stands now, so a request that has been overtaken by other activity is refused rather than posted.
 */
export const trustApproveDisbursement = <ThrowOnError extends boolean = false>(options: Options<TrustApproveDisbursementData, ThrowOnError>): RequestResult<TrustApproveDisbursementResponses, TrustApproveDisbursementErrors, ThrowOnError> => (options.client ?? client).post<TrustApproveDisbursementResponses, TrustApproveDisbursementErrors, ThrowOnError>({ url: '/api/v1/trust/disbursement-requests/{requestId}/approval', ...options });

/**
 * Refuses a pending disbursement request, recording who refused it and why. Nothing reaches the ledger. The refusing member must be somebody other than the one who submitted it — taking back your own request is a withdrawal.
 */
export const trustRejectDisbursement = <ThrowOnError extends boolean = false>(options: Options<TrustRejectDisbursementData, ThrowOnError>): RequestResult<TrustRejectDisbursementResponses, TrustRejectDisbursementErrors, ThrowOnError> => (options.client ?? client).post<TrustRejectDisbursementResponses, TrustRejectDisbursementErrors, ThrowOnError>({
    url: '/api/v1/trust/disbursement-requests/{requestId}/rejection',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Takes back a pending disbursement request the calling member submitted. Recorded rather than deleted — that a payment was proposed and then withdrawn is itself part of the record. Only the submitting member may withdraw; anyone else records a rejection with a reason.
 */
export const trustWithdrawDisbursement = <ThrowOnError extends boolean = false>(options: Options<TrustWithdrawDisbursementData, ThrowOnError>): RequestResult<TrustWithdrawDisbursementResponses, TrustWithdrawDisbursementErrors, ThrowOnError> => (options.client ?? client).post<TrustWithdrawDisbursementResponses, TrustWithdrawDisbursementErrors, ThrowOnError>({
    url: '/api/v1/trust/disbursement-requests/{requestId}/withdrawal',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Lists the firm's trust accounts alphabetically by the name the firm gave each one, closed accounts included: a compliance report is asked about the period an account was live, which is often after it closed, and a listing that hid closed accounts would make that report impossible to ask for. Cursor-paginated. Each row carries the identity a person picks an account by and the last four digits of its number, which is all the platform stores of it.
 */
export const trustListTrustAccounts = <ThrowOnError extends boolean = false>(options?: Options<TrustListTrustAccountsData, ThrowOnError>): RequestResult<TrustListTrustAccountsResponses, TrustListTrustAccountsErrors, ThrowOnError> => (options?.client ?? client).get<TrustListTrustAccountsResponses, TrustListTrustAccountsErrors, ThrowOnError>({ url: '/api/v1/trust/accounts', ...options });

/**
 * Opens a trust account and binds it to one of the firm's offices. The jurisdiction is the office's own and is never chosen here, because the rules require a trust account to sit in the state of the lawyer's office — naming it separately would be a second answer to a question the office already settles. An office that has no jurisdiction recorded still opens an account, and every movement on that account is refused until the office records one, so recording the office's state is what makes the account usable rather than something to redo here. Only the last four digits of the bank account number are taken, because that is all the platform stores of it. The account is pooled interest-bearing unless the firm says otherwise. A retried open returns the account the first call opened rather than opening a second one, which is why the idempotency key is required.
 */
export const trustOpenAccount = <ThrowOnError extends boolean = false>(options: Options<TrustOpenAccountData, ThrowOnError>): RequestResult<TrustOpenAccountResponses, TrustOpenAccountErrors, ThrowOnError> => (options.client ?? client).post<TrustOpenAccountResponses, TrustOpenAccountErrors, ThrowOnError>({
    url: '/api/v1/trust/accounts',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Returns where one trust account stands as of today in the holding office's own time zone: the trust bank account's book balance, the sum of every client ledger under it, how much of that is under disputed-funds holds, the firm's bank-charge cushion where the account has one, how many client ledgers the account carries, and how many payments out are waiting on a decision. Every money figure is computed from dated ledger rows at the moment of asking — the same computation a reconciliation's proof is built on — never read off a stored total, so the figure shown on an account and the figure a period attests to can never come from two different definitions. The cushion reads as null rather than zero on an account that never opened the carve-out, because the firm keeping its own money there is something a firm opts into.
 */
export const trustAccountPosition = <ThrowOnError extends boolean = false>(options: Options<TrustAccountPositionData, ThrowOnError>): RequestResult<TrustAccountPositionResponses, TrustAccountPositionErrors, ThrowOnError> => (options.client ?? client).get<TrustAccountPositionResponses, TrustAccountPositionErrors, ThrowOnError>({ url: '/api/v1/trust/accounts/{trustAccountId}/position', ...options });

/**
 * Returns the firm's disbursement-authorization posture — whether money leaving a client ledger takes a second person (off, above a threshold amount, or always) and whether whoever authorizes it must hold the authority capability — together with every version the firm has ever written. A firm that has never written one has the shipped default: always two-person, no authority requirement.
 */
export const trustReadAuthorizationPolicy = <ThrowOnError extends boolean = false>(options?: Options<TrustReadAuthorizationPolicyData, ThrowOnError>): RequestResult<TrustReadAuthorizationPolicyResponses, TrustReadAuthorizationPolicyErrors, ThrowOnError> => (options?.client ?? client).get<TrustReadAuthorizationPolicyResponses, TrustReadAuthorizationPolicyErrors, ThrowOnError>({ url: '/api/v1/trust/authorization-policy', ...options });

/**
 * Changes the firm's disbursement-authorization posture, as a new immutable version recording who changed it, when, and from what. The change governs NEW authorizations only: a request already pending keeps the policy version it was submitted under, in both directions. Requires the authority capability — relaxing how the firm's client money moves is itself an act of authority over it.
 */
export const trustChangeAuthorizationPolicy = <ThrowOnError extends boolean = false>(options: Options<TrustChangeAuthorizationPolicyData, ThrowOnError>): RequestResult<TrustChangeAuthorizationPolicyResponses, TrustChangeAuthorizationPolicyErrors, ThrowOnError> => (options.client ?? client).put<TrustChangeAuthorizationPolicyResponses, TrustChangeAuthorizationPolicyErrors, ThrowOnError>({
    url: '/api/v1/trust/authorization-policy',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Moves trust funds between two matters of the SAME client. No bank movement happens, so no bank line is posted and no reconciliation item is created. A destination matter belonging to a different client is refused.
 */
export const trustTransferBetweenMatters = <ThrowOnError extends boolean = false>(options: Options<TrustTransferBetweenMattersData, ThrowOnError>): RequestResult<TrustTransferBetweenMattersResponses, TrustTransferBetweenMattersErrors, ThrowOnError> => (options.client ?? client).post<TrustTransferBetweenMattersResponses, TrustTransferBetweenMattersErrors, ThrowOnError>({
    url: '/api/v1/trust/matter-transfers',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Returns one matter's trust ledger: its stored balance, the amount under disputed-funds holds, what is available, and every movement that touched it in effective-date order. A transfer between two matters appears on both.
 */
export const trustMatterLedger = <ThrowOnError extends boolean = false>(options: Options<TrustMatterLedgerData, ThrowOnError>): RequestResult<TrustMatterLedgerResponses, TrustMatterLedgerErrors, ThrowOnError> => (options.client ?? client).get<TrustMatterLedgerResponses, TrustMatterLedgerErrors, ThrowOnError>({ url: '/api/v1/trust/matters/{matterId}/ledger', ...options });

/**
 * Lists the bank statements recorded for one trust account, most recent period first — what a member picks from when starting a reconciliation.
 */
export const trustListBankStatements = <ThrowOnError extends boolean = false>(options: Options<TrustListBankStatementsData, ThrowOnError>): RequestResult<TrustListBankStatementsResponses, TrustListBankStatementsErrors, ThrowOnError> => (options.client ?? client).get<TrustListBankStatementsResponses, TrustListBankStatementsErrors, ThrowOnError>({ url: '/api/v1/trust/bank-statements', ...options });

/**
 * Records one period of a trust bank account as the institution reported it, with its lines, in one atomic write. This is the only external input the trust subsystem has: an item the firm never recorded — a bank fee, a returned deposit, a forged check — exists nowhere in the platform until it arrives here. Balances are signed, because a trust bank account really can be overdrawn. A statement is never edited; a bank that reissues a period is recorded as a new statement naming the one it supersedes.
 */
export const trustRecordBankStatement = <ThrowOnError extends boolean = false>(options: Options<TrustRecordBankStatementData, ThrowOnError>): RequestResult<TrustRecordBankStatementResponses, TrustRecordBankStatementErrors, ThrowOnError> => (options.client ?? client).post<TrustRecordBankStatementResponses, TrustRecordBankStatementErrors, ThrowOnError>({
    url: '/api/v1/trust/bank-statements',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Returns one statement's lines in the order the bank posted them.
 */
export const trustBankStatementLines = <ThrowOnError extends boolean = false>(options: Options<TrustBankStatementLinesData, ThrowOnError>): RequestResult<TrustBankStatementLinesResponses, TrustBankStatementLinesErrors, ThrowOnError> => (options.client ?? client).get<TrustBankStatementLinesResponses, TrustBankStatementLinesErrors, ThrowOnError>({ url: '/api/v1/trust/bank-statements/{statementId}/lines', ...options });

/**
 * Reads a statement file the firm exported from its bank and reports what is in it: the column mapping it resolved, every row it could read and what each would become, every row it could not and why, and the totals. NOTHING IS STORED — running this is not a decision to import anything, and the report is often the reason to decide. The date convention is stated by the caller and never detected: a date this endpoint cannot read is a reported row, never a date reinterpreted under another convention.
 */
export const trustPreviewStatementImport = <ThrowOnError extends boolean = false>(options: Options<TrustPreviewStatementImportData, ThrowOnError>): RequestResult<TrustPreviewStatementImportResponses, TrustPreviewStatementImportErrors, ThrowOnError> => (options.client ?? client).post<TrustPreviewStatementImportResponses, TrustPreviewStatementImportErrors, ThrowOnError>({
    url: '/api/v1/trust/bank-statements/import/preview',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Records a statement from a file that was previewed and confirmed. The file is re-read here rather than taken from the preview, and the fingerprint the preview returned must still match it — so a file that changed between being reviewed and being agreed to is refused rather than stored. The response reports what was actually recorded, including how many rows could not be read.
 */
export const trustImportBankStatement = <ThrowOnError extends boolean = false>(options: Options<TrustImportBankStatementData, ThrowOnError>): RequestResult<TrustImportBankStatementResponses, TrustImportBankStatementErrors, ThrowOnError> => (options.client ?? client).post<TrustImportBankStatementResponses, TrustImportBankStatementErrors, ThrowOnError>({
    url: '/api/v1/trust/bank-statements/import',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Lists the reconciliations recorded for one trust account, most recently opened first. A closed one carries the proof it froze, which is what the firm attested to for that period rather than what is true now.
 */
export const trustListReconciliations = <ThrowOnError extends boolean = false>(options: Options<TrustListReconciliationsData, ThrowOnError>): RequestResult<TrustListReconciliationsResponses, TrustListReconciliationsErrors, ThrowOnError> => (options.client ?? client).get<TrustListReconciliationsResponses, TrustListReconciliationsErrors, ThrowOnError>({ url: '/api/v1/trust/reconciliations', ...options });

/**
 * Opens a reconciliation of one recorded bank statement. The trust account is taken from the statement rather than from the caller, so a reconciliation about one account's statement and another account's ledger is not expressible.
 */
export const trustOpenReconciliation = <ThrowOnError extends boolean = false>(options: Options<TrustOpenReconciliationData, ThrowOnError>): RequestResult<TrustOpenReconciliationResponses, TrustOpenReconciliationErrors, ThrowOnError> => (options.client ?? client).post<TrustOpenReconciliationResponses, TrustOpenReconciliationErrors, ThrowOnError>({
    url: '/api/v1/trust/reconciliations',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Returns one reconciliation and its three-way proof as it stands NOW: the statement's closing balance adjusted for items the firm recorded that have not reached the bank, the trust bank account's book balance, and the sum of the client ledgers — each as of the statement's period end. When the three do not agree it names which leg is out and by how much; it never forces them into agreement. A closed reconciliation also carries the proof it froze, and the two may differ, which is the ledger having moved since somebody attested to the period.
 */
export const trustGetReconciliation = <ThrowOnError extends boolean = false>(options: Options<TrustGetReconciliationData, ThrowOnError>): RequestResult<TrustGetReconciliationResponses, TrustGetReconciliationErrors, ThrowOnError> => (options.client ?? client).get<TrustGetReconciliationResponses, TrustGetReconciliationErrors, ThrowOnError>({ url: '/api/v1/trust/reconciliations/{reconciliationId}', ...options });

/**
 * Returns the statement lines this reconciliation has not accounted for, the recorded items it has not accounted for, and the candidate pairings between them with the reasons each is a candidate. NOTHING IS MATCHED BY THIS ENDPOINT, and nothing in the platform matches on its own: a wrong automatic match makes the totals tie out while the ledger and the bank disagree about which events happened, which is the discrepancy a reconciliation exists to find.
 */
export const trustReconciliationSuggestions = <ThrowOnError extends boolean = false>(options: Options<TrustReconciliationSuggestionsData, ThrowOnError>): RequestResult<TrustReconciliationSuggestionsResponses, TrustReconciliationSuggestionsErrors, ThrowOnError> => (options.client ?? client).get<TrustReconciliationSuggestionsResponses, TrustReconciliationSuggestionsErrors, ThrowOnError>({ url: '/api/v1/trust/reconciliations/{reconciliationId}/suggestions', ...options });

/**
 * Returns every match recorded on one reconciliation, oldest first, each with the statement line and the recorded item it pairs — the record of what members asserted about this period. Withdrawn matches are listed too, carrying who took the assertion back and when: a withdrawal is appended rather than deleted, and the list a person reads must show that the pairing was once made. What is still unaccounted for is a different question, answered by the suggestions read beside this one.
 */
export const trustReconciliationMatches = <ThrowOnError extends boolean = false>(options: Options<TrustReconciliationMatchesData, ThrowOnError>): RequestResult<TrustReconciliationMatchesResponses, TrustReconciliationMatchesErrors, ThrowOnError> => (options.client ?? client).get<TrustReconciliationMatchesResponses, TrustReconciliationMatchesErrors, ThrowOnError>({ url: '/api/v1/trust/reconciliations/{reconciliationId}/matches', ...options });

/**
 * Records a member's assertion that one statement line and one recorded ledger entry are the same event. Both ends are named by the caller. The book side is a ledger entry rather than a trust movement because an earned-fee transfer out of trust posts a bank-affecting entry and no movement record, and an item that could never be matched would sit outstanding forever.
 */
export const trustRecordReconciliationMatch = <ThrowOnError extends boolean = false>(options: Options<TrustRecordReconciliationMatchData, ThrowOnError>): RequestResult<TrustRecordReconciliationMatchResponses, TrustRecordReconciliationMatchErrors, ThrowOnError> => (options.client ?? client).post<TrustRecordReconciliationMatchResponses, TrustRecordReconciliationMatchErrors, ThrowOnError>({
    url: '/api/v1/trust/reconciliations/{reconciliationId}/matches',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Takes back a match a member recorded. Appended rather than deleted — that somebody asserted the pairing and then took it back stays on the record — and the item becomes outstanding again.
 */
export const trustWithdrawReconciliationMatch = <ThrowOnError extends boolean = false>(options: Options<TrustWithdrawReconciliationMatchData, ThrowOnError>): RequestResult<TrustWithdrawReconciliationMatchResponses, TrustWithdrawReconciliationMatchErrors, ThrowOnError> => (options.client ?? client).post<TrustWithdrawReconciliationMatchResponses, TrustWithdrawReconciliationMatchErrors, ThrowOnError>({ url: '/api/v1/trust/reconciliations/{reconciliationId}/matches/{matchId}/withdrawal', ...options });

/**
 * Closes a reconciliation and freezes what its proof said at that moment. Nothing else is written: no ledger entry, no movement, no correction to anything the proof disagreed with. A period that did NOT balance closes exactly as readily as one that did, recording that it did not tie out and by how much — a record of a problem is the point, and the frozen figures never change afterwards even if a backdated entry moves the live proof.
 */
export const trustCloseReconciliation = <ThrowOnError extends boolean = false>(options: Options<TrustCloseReconciliationData, ThrowOnError>): RequestResult<TrustCloseReconciliationResponses, TrustCloseReconciliationErrors, ThrowOnError> => (options.client ?? client).post<TrustCloseReconciliationResponses, TrustCloseReconciliationErrors, ThrowOnError>({ url: '/api/v1/trust/reconciliations/{reconciliationId}/close', ...options });

/**
 * The account's checks: payments waiting to be printed, the register of every check number used with its status, the current check stock, and the next number. The register is the same read the reconciliation report's check register uses.
 */
export const trustChecks = <ThrowOnError extends boolean = false>(options: Options<TrustChecksData, ThrowOnError>): RequestResult<TrustChecksResponses, TrustChecksErrors, ThrowOnError> => (options.client ?? client).get<TrustChecksResponses, TrustChecksErrors, ThrowOnError>({ url: '/api/v1/trust/checks', ...options });

/**
 * Numbers the chosen payments from the account's next check number, in the order given, and returns what each check says. The browser composes the PDF. Printing moves no money: the payment was approved when it was recorded.
 */
export const trustPrintChecks = <ThrowOnError extends boolean = false>(options: Options<TrustPrintChecksData, ThrowOnError>): RequestResult<TrustPrintChecksResponses, TrustPrintChecksErrors, ThrowOnError> => (options.client ?? client).post<TrustPrintChecksResponses, TrustPrintChecksErrors, ThrowOnError>({
    url: '/api/v1/trust/checks/print',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Says which checks of a print came out right and which were spoiled. A spoiled check keeps its number in the register and its payment goes back to the print queue.
 */
